package tools

import "minimalharness/internal/llm"

func Defs() []llm.ToolDef {
	return []llm.ToolDef{
		llm.Tool("read", "Read a file (with 1-based line offset and limit) or list a directory. Directory pages default to 100 names, max 500, with offset at most 10001. File scanning is bounded at 32 MiB; partial reads of files larger than 8 MiB do not establish the version required for line edits. Image files (png, jpg, gif, webp) are returned as an image you can see, not as text — use read to look at a screenshot or photo.", `{"type":"object","additionalProperties":false,"properties":{"path":{"type":"string"},"offset":{"type":"integer","minimum":0},"limit":{"type":"integer","minimum":0}},"required":["path"]}`),
		llm.Tool(GuidanceTool, "Read the next bytes from an applicable project guidance source listed by the harness. Copy target, path, SHA-256 and next byte offset from the guidance message, or previous chunk. Read until More is false when the remainder is needed. The limit defaults to 8192 bytes.", `{"type":"object","additionalProperties":false,"properties":{"target":{"type":"string","minLength":1},"path":{"type":"string","minLength":1},"sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"offset":{"type":"integer","minimum":0},"limit":{"type":"integer","minimum":4,"maximum":8192}},"required":["target","path","sha256","offset"]}`),
		llm.Tool(GitStatusTool, "Read the current branch and short working tree status for this trusted workspace. No arguments; available independently of Bash.", `{"type":"object","additionalProperties":false,"properties":{}}`),
		llm.Tool("write", "Create a file. By default it fails if the file already exists — use edit then. Pass overwrite:true to replace an existing file wholesale; prefer edit for a small change.", `{"type":"object","additionalProperties":false,"properties":{"path":{"type":"string"},"content":{"type":"string"},"overwrite":{"type":"boolean"}},"required":["path","content"]}`),
		llm.Tool("edit", "Replace text in an existing file. Two forms: oldText (replaced exactly once) or startLine/endLine (1-based, inclusive; endLine defaults to startLine) to replace those lines with newText, ignoring oldText. The line form requires a known version from a read or full write in this session. Successful edits update that version only if the file still matched it before editing (and line count is unchanged); otherwise read the target lines again before a line edit.", `{"type":"object","additionalProperties":false,"properties":{"path":{"type":"string"},"oldText":{"type":"string"},"newText":{"type":"string"},"startLine":{"type":"integer","minimum":1},"endLine":{"type":"integer","minimum":1}},"required":["path","newText"],"anyOf":[{"required":["oldText"]},{"required":["startLine"]}]}`),
		llm.Tool("bash", "Run a shell command in the workspace root, or pass killJobId to stop a running background job. Each call is a fresh shell; cd does not persist between calls — pass cwd to run in a subdirectory, or prefix the command with `cd <dir> && `. Timeout in seconds, default 120, max 600; a background:true job has no timeout unless one is passed. Pass background:true for a command that will not exit on its own (dev server, watcher): it returns at once with a job id, and its output is delivered at the next step. Keep the service in the foreground of that shell; "+bashShellCompletionPolicy+" A never-ending job never blocks the turn from ending: the turn ends after a short drain wait, and you can read its partial output from the output file. Captured output is limited per command and per session. Delivered output files may be removed after seven days when Bash is used again. Every result header names the directory the call ran in.", `{"type":"object","additionalProperties":false,"properties":{"command":{"type":"string"},"timeout":{"type":"integer","minimum":0},"background":{"type":"boolean"},"cwd":{"type":"string"},"killJobId":{"type":"string","minLength":1}},"oneOf":[{"required":["command"],"not":{"required":["killJobId"]}},{"required":["killJobId"],"not":{"required":["command"]}}]}`),
		llm.Tool("grep", "Search file contents with a regex. Prefer this over bash grep/rg. Returns file:line matches, capped (truncation is marked).", `{"type":"object","additionalProperties":false,"properties":{"pattern":{"type":"string"},"path":{"type":"string"},"include":{"type":"string"},"exclude":{"type":"string"},"context":{"type":"integer","minimum":0},"maxMatches":{"type":"integer","minimum":0}},"required":["pattern"]}`),
		llm.Tool("glob", "List files matching a glob pattern, e.g. **/*.go. Prefer this over bash find/ls for discovering files. Results are sorted and capped; quoted paths preserve whitespace and control characters. An incomplete search reports a lower-bound count and a warning.", `{"type":"object","additionalProperties":false,"properties":{"pattern":{"type":"string"},"path":{"type":"string"},"limit":{"type":"integer","minimum":0}},"required":["pattern"]}`),
		llm.Tool("load_skill", "Load the full text of an available skill by name when its guidance is needed for the current task. The skill names and one-line descriptions are in the system prompt. Pass reference (a file name from the skill's references/ footer) to read one reference file instead of the whole skill.", `{"type":"object","additionalProperties":false,"properties":{"name":{"type":"string"},"reference":{"type":"string"}},"required":["name"]}`),
		llm.Tool("webfetch", "Fetch a URL and return its content as Markdown (HTML is converted to Markdown, keeping headings, lists, links, code and tables; scripts and styles are dropped). Use this to read web pages, docs and API responses instead of curl. Returns up to 30000 characters per call; use offset to page through a long page. format=text returns plain text instead of Markdown; timeout is seconds (default 30, max 120). Private, loopback (except localhost) and cloud-metadata addresses are refused, and cross-host redirects are not followed.", `{"type":"object","additionalProperties":false,"properties":{"url":{"type":"string"},"format":{"type":"string","enum":["markdown","text"]},"offset":{"type":"integer","minimum":0},"timeout":{"type":"integer","minimum":0}},"required":["url"]}`),
		llm.Tool("ask_user", "Ask the user structured questions when a decision needs their input instead of guessing: 1-4 questions, each with 2-4 options (plus free-text Other). Use it in plan mode to clarify requirements, and anywhere a choice changes what you will do. The user picks options or types their own answer; their answers come back as this call's result.", `{"type":"object","additionalProperties":false,"properties":{"questions":{"type":"array","minItems":1,"maxItems":4,"items":{"type":"object","properties":{"question":{"type":"string"},"header":{"type":"string"},"multiSelect":{"type":"boolean"},"options":{"type":"array","minItems":2,"maxItems":4,"items":{"type":"object","properties":{"label":{"type":"string"},"description":{"type":"string"}},"required":["label"]}}},"required":["question","options"]}}},"required":["questions"]}`),
	}
}
